package equivalent;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

class ClonePair4925DifferenceFindingTest {

    private final ClonePair4925 subject = new ClonePair4925();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: return_value.
     * Difference manifestation: the methods return different values.
     */
    @Test
    @BehavioralDifference(DifferenceType.RETURN_VALUE)
    void methodsRoundTheShiftedArgumentDifferentlyInTheLastBranch() {
        // method1 subtracts the double constant 2.625 / 2.75 before narrowing back to float,
        // whereas method2 subtracts the float constant 2.625f / 2.75f.
        float method1Result = subject.method1(1.25f);
        float method2Result = subject.method2(1.25f);

        assertEquals(1.6445312f, method1Result);
        assertEquals(1.6445314f, method2Result);
        assertNotEquals(Float.floatToIntBits(method1Result), Float.floatToIntBits(method2Result));
    }
}
